package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import org.json.*;
public final class HudRulesInstrumentation extends Instrumentation {
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();PrintStream original=System.out;try{File dir=getTargetContext().getFilesDir();ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream capture=new PrintStream(bytes,true,"UTF-8")){System.setOut(capture);HudRulesTest.main(new String[]{new File(dir,"hud-rules.bin").getPath()});HudCandidatesTest.main(new String[]{new File(dir,"hud-candidates.bin").getPath()});}finally{System.setOut(original);}String[] lines=bytes.toString("UTF-8").trim().split("\\r?\\n");if(lines.length!=2||!lines[0].startsWith("PASS_HUD_RULES ")||!lines[1].startsWith("PASS_HUD_CANDIDATES "))throw new AssertionError("Verifiers did not complete");JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_HUD_RULES_CANDIDATES");report.put("rules_verification",lines[0]);report.put("candidates_verification",lines[1]);report.put("api",Build.VERSION.SDK_INT);report.put("game_steps",0);report.put("gpu_composition",false);try(FileOutputStream out=getTargetContext().openFileOutput("hud-rules-report.json",0)){out.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);}catch(Throwable failure){System.setOut(original);android.util.Log.e("NFSUGHudRules","Failed",failure);result.putString("stream","FAIL: "+failure);finish(Activity.RESULT_CANCELED,result);}}
}
